head.script:
scwin.onpageload = function() {
	WebSquare.wUnit.getObjById('cal_calendar').setHolidayRef("data:dtl_dataList1.col1");
};
scwin.onpageunload = function() {};
scwin.cal_calendar_ondateselect = function(dateStr, dateObj) {
    var arrRows = dtl_dataList1.getMatchedIndex("col1", dateStr, true);
    if (arrRows.length == 0) {
        var iRow = dtl_dataList1.insertRow();
        dtl_dataList1.setCellData(iRow, "col1", dateStr);
    } else {
        for (var i = 0; i < arrRows.length; i++) {
            dtl_dataList1.removeRow(arrRow[i]);
        }
        dtl_dataList1.reform();
    }
};
scwin.grd1_onrownumclick = function(row) {};
scwin.grd1_onfilereadend = function(value) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.checkSimulate1 = function() {
    scwin.simulateWrapper('#grd1_cell_1_0', 'key-combo', {
        combo: 'DELETE'
    });
}
scwin.checkVal = function() {
    return !WebSquare.wUnit.getJq('#cal_calendar_cell_1_1').hasClass('w2calendar_holiday');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_calendar_cell_1_1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_calendar_cell_1_2').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_calendar_cell_1_3').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_cell_1_0').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_cell_1_0').focus()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.checkSimulate1()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
